# normalize_expense.py\n# [SAME-SCENARIO] normalizes extracted expense fields into a standard JSON schema\n\nfrom document_models import NormalizedExpense, NormalizationResult\n\ndef normalize_expense(raw_response: dict) -> NormalizationResult:\n    # Extract required fields, applying default values when missing\n    vendor = raw_response.get('vendor', '')\n    date = raw_response.get('date', '')\n    total = raw_response.get('total', 0.0)\n    items = raw_response.get('items', [])\n    # Build normalized schema\n    normalized = NormalizedExpense(\n        vendor=vendor,\n        date=date,\n        total=total,\n        items=items\n    )\n    return NormalizationResult(\n        expense=normalized,\n        success=True,\n        message='Normalization succeeded'\n    )\n
